"""Generate creative assets (AI image, branded card, copy) from any prompt for free.

Supported free providers:
- Pollinations AI (Keyless, 100% free, unlimited FLUX.1 / SDXL)
- Hugging Face Inference (Free tier using HF_TOKEN)
- Google Gemini (Free tier using GEMINI_API_KEY)
- Local Pillow Typography Engine (100% free, offline branded card)

Usage:
    # List prompts generated by recent Actions:
    python scripts/generate_creative.py --list

    # Generate content for an existing prompt ID:
    python scripts/generate_creative.py --prompt-id 17

    # Generate content from custom text:
    python scripts/generate_creative.py --title "Festive Sale" --hook "Transform Your Living Room for Under ₹2,999" --prompt "Modern Indian living room decorated for Diwali with warm fairy lights and brass diya"
"""
from __future__ import annotations

import argparse
import json
import logging
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")

from src.generation.creative_forge import CreativeForge
from src.shared.config import settings

logging.basicConfig(level=logging.INFO, format="%(message)s")
logger = logging.getLogger("generate_creative")


def find_prompt_in_manifests(prompt_id: int | str) -> tuple[dict, dict] | None:
    manifest_dir = ROOT / "data" / "site_manifests"
    str_id = str(prompt_id)

    for path in manifest_dir.glob("*.json"):
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue

        # Check standard entries
        entries = data.get("entries", [])
        for entry in entries:
            if str(entry.get("prompt_id")) == str_id or str(entry.get("id")) == str_id:
                return entry, data.get("business", {"name": path.stem, "color_hex": "#1F6F68"})

        # Check leads digests
        for digest in data.get("digests", []):
            for lead in digest.get("leads", []):
                for idx, p in enumerate(lead.get("prompts", [])):
                    if str_id in (f"lead-{lead.get('name')}-{idx}", p.get("title", "")):
                        return p, {
                            "name": lead.get("name", "Lead"),
                            "color_hex": "#D97706",
                            "meta_description": lead.get("niche", ""),
                        }

    return None


def list_prompts() -> None:
    manifest_dir = ROOT / "data" / "site_manifests"
    print("\n--- Available Prompts from Actions Runs ---")
    for path in manifest_dir.glob("*.json"):
        if path.name == "_leads.json":
            data = json.loads(path.read_text(encoding="utf-8"))
            for digest in data.get("digests", []):
                date = digest.get("date", "")
                for lead in digest.get("leads", []):
                    name = lead.get("name", "Unknown")
                    for idx, p in enumerate(lead.get("prompts", [])):
                        print(f"[{date}] Lead: {name} | Title: '{p.get('title')}' (Score: {p.get('score')})")
        else:
            data = json.loads(path.read_text(encoding="utf-8"))
            biz_name = data.get("business", {}).get("name", path.stem)
            for entry in data.get("entries", []):
                pid = entry.get("prompt_id", entry.get("id"))
                title = entry.get("title")
                score = entry.get("score")
                fmt = entry.get("format", "single image")
                print(f"[ID: {pid:>2}] {biz_name:<16} | '{title}' ({fmt}, Score: {score})")
    print("-------------------------------------------\n")


def main() -> None:
    parser = argparse.ArgumentParser(description="Generate creative assets from prompts for free.")
    parser.add_argument("--list", action="store_true", help="List all generated prompts available in manifests")
    parser.add_argument("--prompt-id", type=str, help="Prompt ID to generate content for")
    parser.add_argument("--title", type=str, help="Custom prompt title")
    parser.add_argument("--hook", type=str, help="Custom ad hook / overlay text")
    parser.add_argument("--prompt", type=str, help="Custom visual scene description")
    parser.add_argument("--visual-scene", type=str, help="Physical scene description for FLUX image generator")
    parser.add_argument("--hook-type", type=str, default="roi_proof", help="Hook type (contrarian, roi_proof, curiosity_gap, before_after, framework)")
    parser.add_argument("--handle", type=str, default="aimagix.studio", help="Instagram handle for watermark footer")
    parser.add_argument("--brand", type=str, default="Aimagix Studio", help="Business or brand name")
    parser.add_argument("--color", type=str, default="#1F6F68", help="Brand hex color for overlays")
    parser.add_argument("--format", type=str, default="single image", choices=["single image", "reel"])

    args = parser.parse_args()

    if args.list:
        list_prompts()
        return

    prompt_data = None
    business_profile = {"name": args.brand, "color_hex": args.color, "instagram_handle": args.handle}

    if args.prompt_id:
        found = find_prompt_in_manifests(args.prompt_id)
        if not found:
            print(f"Error: Prompt ID '{args.prompt_id}' not found in data/site_manifests/.")
            print("Run 'python scripts/generate_creative.py --list' to see available IDs.")
            sys.exit(1)
        prompt_data, business_profile = found
        business_profile.setdefault("instagram_handle", args.handle)
        print(f"Found prompt: '{prompt_data.get('title')}' for {business_profile.get('name')}")
    elif args.prompt or args.hook or args.title:
        prompt_data = {
            "title": args.title or "Custom Ad",
            "hook": args.hook or args.title or "Exclusive Offer",
            "hook_type": args.hook_type,
            "visual_scene": args.visual_scene or args.prompt or "",
            "angle": "Promotional",
            "prompt_text": args.prompt or args.hook or "Professional modern visual",
            "format": args.format,
        }
    else:
        print("Please provide --prompt-id, or --title/--hook/--prompt, or run with --list.")
        parser.print_help()
        sys.exit(0)

    print("\nGenerating creative content using free AI pipelines...")
    forge = CreativeForge()
    res = forge.render_prompt(prompt_data, business_profile, index=0)

    print("\n=== Content Generated Successfully! ===")
    print(f"Asset Path  : {res.get('asset_path')}")
    print(f"Asset Type  : {res.get('asset_type')}")
    if res.get("warnings"):
        print(f"Warnings    : {res.get('warnings')}")

    if prompt_data.get("caption"):
        print("\n--- Social Post Caption ---")
        print(prompt_data["caption"])

    if prompt_data.get("hashtags"):
        print("\n--- Hashtags ---")
        print(" ".join(prompt_data["hashtags"]))

    if prompt_data.get("recommended_post_time"):
        print(f"\nRecommended Post Time: {prompt_data['recommended_post_time']}")
    print("=======================================\n")


if __name__ == "__main__":
    main()
